import{_ as r,o as a,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"CephFS Code Walkthrough: CephFS Mirroring Part 2","description":"","frontmatter":{"title":"CephFS Code Walkthrough: CephFS Mirroring Part 2","date":"2021-04-27T00:00:00.000Z","updated":"2021-04-27T00:00:00.000Z","tags":["CephFS","Mirroring","Demurrer Daemon","Snapshot Synchronization","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/CephFS_Code_Walkthrough_-_CephFS_Mirroring_Part_2.md","filePath":"posts/2021/CephFS_Code_Walkthrough_-_CephFS_Mirroring_Part_2.md","lastUpdated":1780459816000}'),o={name:"posts/2021/CephFS_Code_Walkthrough_-_CephFS_Mirroring_Part_2.md"};function t(n,e,h,s,u,d){return a(),i("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-demurrer-daemon-后续讨论" tabindex="-1">会议主题：Demurrer Daemon 后续讨论 <a class="header-anchor" href="#会议主题-demurrer-daemon-后续讨论" aria-label="Permalink to &quot;会议主题：Demurrer Daemon 后续讨论&quot;">​</a></h4><h4 id="参会人员-ceph-分布式存储研发团队" tabindex="-1">参会人员：Ceph 分布式存储研发团队 <a class="header-anchor" href="#参会人员-ceph-分布式存储研发团队" aria-label="Permalink to &quot;参会人员：Ceph 分布式存储研发团队&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Demurrer Daemon 概述</strong>：</p><ul><li>Demurrer Daemon 负责在主集群和次集群之间同步 CephFS 快照。</li><li>每个集群配备一个 Demurrer Daemon，支持处理多个文件系统。</li><li>采用推送模型，数据从主集群推送到次集群。</li></ul></li><li><p><strong>技术细节</strong>：</p><ul><li>Demurrer Daemon 使用 libcephfs 客户端库与本地和远程集群通信。</li><li>支持增量同步，但目前 Pacific 版本仅支持批量复制。</li></ul></li><li><p><strong>配置和运行</strong>：</p><ul><li>主集群需要 ceph 配置文件和密钥环。</li><li>次集群支持两种添加方式：通过 pr add 接口和通过引导（bootstrapping）。</li><li>建议每个集群只运行一个 Demurrer Daemon。</li></ul></li><li><p><strong>代码实现</strong>：</p><ul><li>从 main.c 开始，进行基本初始化，创建 messenger 和客户端。</li><li>使用 Cluster Watcher 订阅 fs map，处理镜像启用和禁用等事件。</li><li>使用定时器线程驱动异步操作，处理镜像启用、禁用、添加和移除对等体等操作。</li></ul></li><li><p><strong>同步机制</strong>：</p><ul><li>使用实例观察者和镜像观察者处理通知消息。</li><li>通过引导令牌在主集群中导入次集群信息，存储在 mon config store 中。</li><li>每个对等体分配多个线程进行快照同步，每个线程处理一个目录。</li></ul></li><li><p><strong>增量同步</strong>：</p><ul><li>通过比较快照 ID 和元数据来识别删除和重命名操作。</li><li>使用 dirty snap id 扩展属性来确定是否可以进行增量同步。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>继续完善 Demurrer Daemon 的增量同步功能。</li><li>测试和验证多对等体支持。</li><li>优化配置选项和性能。</li></ul></li></ol><h4 id="会议结论" tabindex="-1">会议结论： <a class="header-anchor" href="#会议结论" aria-label="Permalink to &quot;会议结论：&quot;">​</a></h4><ul><li>Demurrer Daemon 的设计和实现已基本完成，但仍需进一步测试和优化。</li><li>增量同步功能是当前的重点开发方向。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>继续开发和测试增量同步功能。</li><li>验证多对等体支持的可行性。</li><li>优化配置选项和性能，提升用户体验。</li></ul><h4 id="会议记录人-记录人姓名" tabindex="-1">会议记录人：[记录人姓名] <a class="header-anchor" href="#会议记录人-记录人姓名" aria-label="Permalink to &quot;会议记录人：[记录人姓名]&quot;">​</a></h4><h4 id="会议结束时间-具体时间" tabindex="-1">会议结束时间：[具体时间] <a class="header-anchor" href="#会议结束时间-具体时间" aria-label="Permalink to &quot;会议结束时间：[具体时间]&quot;">​</a></h4>',13)])])}const m=r(o,[["render",t]]);export{_ as __pageData,m as default};
